package com.bank.classload.service;

public class GatewayLoaderService {

    // ═══ ClassNotFoundException: dynamic loading — expected failure ═══
    public String loadGatewayDynamic(String className) {
        try {
            Class<?> clazz = Class.forName(className);  // dynamic — string-based
            return "Loaded: " + clazz.getSimpleName();
        } catch (ClassNotFoundException e) {
            // CHECKED — compiler forces handling. Expected for optional plugins.
            return "Gateway not available: " + className + " (add JAR to classpath)";
        }
    }

    // ═══ NoClassDefFoundError: direct reference — unexpected failure ═══
    // If we had: import com.vendor.PaymentGateway;
    // And used: new PaymentGateway();
    // But the vendor JAR is missing at runtime → NoClassDefFoundError!
    // We can't demonstrate this easily (it's a deployment issue).

    // ═══ Static initializer failure → NoClassDefFoundError on retry ═══
    public String loadBrokenClass() {
        try {
            Class.forName("com.bank.classload.service.GatewayLoaderService$BrokenStatic");
            return "Loaded";
        } catch (ExceptionInInitializerError e) {
            return "First load: static init failed — " + e.getCause().getMessage();
        } catch (NoClassDefFoundError e) {
            return "Retry: NoClassDefFoundError — class marked as failed!";
        }
    }

    // Inner class with broken static initializer:
    static class BrokenStatic {
        static {
            if (true) throw new RuntimeException("Static init BOOM!");
            // First load: ExceptionInInitializerError
            // All subsequent loads: NoClassDefFoundError (JVM won't retry)
        }
    }
}
