// ─── File: src/test/java/com/bank/classload/ClassLoadingTest.java ───
package com.bank.classload;

import com.bank.classload.service.GatewayLoaderService;
import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class ClassLoadingTest {

    GatewayLoaderService service = new GatewayLoaderService();

    // ═══ ClassNotFoundException: class not on classpath ═══
    @Test
    void classNotFound_dynamicLoading() {
        String result = service.loadGatewayDynamic("com.vendor.NonExistentGateway");
        assertThat(result).contains("not available");
        // Class.forName with non-existent class → ClassNotFoundException (checked)
    }

    @Test
    void classFound_dynamicLoading() {
        String result = service.loadGatewayDynamic("java.lang.String");
        assertThat(result).isEqualTo("Loaded: String");
        // String exists → loaded successfully
    }

    @Test
    void classNotFoundException_isCheckedException() {
        assertThat(Exception.class.isAssignableFrom(ClassNotFoundException.class)).isTrue();
        assertThat(RuntimeException.class.isAssignableFrom(ClassNotFoundException.class)).isFalse();
        // ClassNotFoundException extends Exception (checked!) — NOT RuntimeException
    }

    // ═══ NoClassDefFoundError: Error, not Exception ═══
    @Test
    void noClassDefFoundError_isAnError() {
        assertThat(Error.class.isAssignableFrom(NoClassDefFoundError.class)).isTrue();
        assertThat(Exception.class.isAssignableFrom(NoClassDefFoundError.class)).isFalse();
        // NoClassDefFoundError extends Error — NOT Exception!
    }

    // ═══ Static init failure → NoClassDefFoundError on retry ═══
    @Test
    void staticInitFailure_causesNoClassDefFoundOnRetry() {
        // First attempt: ExceptionInInitializerError (wraps the static block's exception)
        String first = service.loadBrokenClass();
        assertThat(first).contains("static init failed");

        // Second attempt: NoClassDefFoundError (class marked as failed — won't retry!)
        String second = service.loadBrokenClass();
        assertThat(second).contains("NoClassDefFoundError");
        // JVM remembers: "this class failed to initialize" — never tries again.
    }

    @Test
    void summary() {
        // ClassNotFoundException:
        //   Type: checked Exception
        //   When: Class.forName("X") — dynamic, string-based
        //   Fix: add JAR, fix class name
        //   Catch? YES (checked — must handle)

        // NoClassDefFoundError:
        //   Type: Error (unchecked)
        //   When: direct reference to class that's missing at runtime
        //   Fix: fix deployment, include dependency JAR
        //   Catch? NO (Error — deployment problem)
        assertThat(true).isTrue();
    }
}
